  ($q$n02$q$, $q$numbers$q$, 1, $q$Nine to nineteen$q$, $j$[{"id":"rule-28","type":"rule","title":"Two-digit numbers: sip + unit","body":"Put the unit number after sip for two-digit numbers 11-19. The only exception is 11, which is sip-et, not sip-neung.","source":"Essential Thai (Higbie), p.17"},{"id":"wi-19","type":"wordIntro","word":{"thai":"เก้า","roman":"kâo","english":"nine"},"source":"Essential Thai (Higbie), p.17"},{"id":"wi-20","type":"wordIntro","word":{"thai":"สิบ","roman":"sìp","english":"ten"},"source":"Essential Thai (Higbie), p.17"},{"id":"so-24","type":"sentenceOrder","prompt":"Nine, ten","tileUnit":"word","words":{"a":{"roman":"kâo","thai":"เก้า"},"b":{"roman":"sìp","thai":"สิบ"},"x0":{"thai":"หนึ่ง","roman":"nɯ̀ng"},"x1":{"thai":"สี่","roman":"sìi"}},"poolOrder":["b","x0","a","x1"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.17"},{"id":"so-25","type":"sentenceOrder","prompt":"Eight, nine, ten","tileUnit":"word","words":{"a":{"roman":"pɛ̀ɛt","thai":"แปด"},"b":{"roman":"kâo","thai":"เก้า"},"c":{"roman":"sìp","thai":"สิบ"},"x0":{"thai":"เจ็ด","roman":"jèt"},"x1":{"thai":"หก","roman":"hòk"}},"poolOrder":["a","x0","c","x1","b"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.17"},{"id":"so-31","type":"sentenceOrder","prompt":"Thirteen, fourteen","tileUnit":"word","words":{"a":{"roman":"sìp","thai":"สิบ"},"b":{"roman":"sǎam","thai":"สาม"},"c":{"roman":"sìp","thai":"สิบ"},"d":{"roman":"sìi","thai":"สี่"},"x0":{"thai":"เจ็ด","roman":"jèt"},"x1":{"thai":"ห้า","roman":"hâa"}},"poolOrder":["x0","x1","a","c","b","d"],"correctOrder":["a","b","c","d"],"source":"Essential Thai (Higbie), p.17"},{"id":"mc-32","type":"translationChoice","thai":"สิบหกสิบเจ็ด","roman":"sìp-hòk sìp-jèt","options":[{"text":"Seventeen, eighteen","correct":false},{"text":"Eighteen, nineteen","correct":false},{"text":"Sixteen, seventeen","correct":true},{"text":"Fifteen, sixteen","correct":false}],"source":"Essential Thai (Higbie), p.17","parts":["สิบ","