̌ɔng","options":[{"text":"Eleven, twelve","correct":true},{"text":"Ten, eleven","correct":false},{"text":"Twelve, thirteen","correct":false},{"text":"Thirteen, fourteen","correct":false}],"source":"Essential Thai (Higbie), p.17","parts":["สิบ","เอ็ด","สิบ","สอง"]},{"id":"match-184","type":"match","pairs":[{"thai":"เก้า","roman":"kâo","english":"nine"},{"thai":"สิบ","roman":"sìp","english":"ten"},{"thai":"ศูนย์","roman":"sǔun","english":"zero"},{"thai":"เอ็ด","roman":"èt","english":"one (in 11, 21, 31… — \"-ty-one\")"}],"source":"Essential Thai (Higbie), p.17"}]$j$::jsonb),
  ($q$n03$q$, $q$numbers$q$, 2, $q$Tens and two-digit numbers$q$, $j$[{"id":"rule-35","type":"rule","title":"Tens: unit + sip (except twenty)","body":"\"For 20, 30, 40, etc, put the unit number before sip. \"Twenty\" is an exception — it's yee-sip, not sawng-sip.","source":"Essential Thai (Higbie), p.17"},{"id":"so-38","type":"sentenceOrder","prompt":"Forty, fifty","tileUnit":"word","words":{"a":{"roman":"sìi","thai":"สี่"},"b":{"roman":"sìp","thai":"สิบ"},"c":{"roman":"hâa","thai":"ห้า"},"d":{"roman":"sìp","thai":"สิบ"},"x0":{"thai":"แปด","roman":"pɛ̀ɛt"},"x1":{"thai":"หก","roman":"hòk"}},"poolOrder":["d","c","b","a","x1","x0"],"correctOrder":["a","b","c","d"],"source":"Essential Thai (Higbie), p.17"},{"id":"mc-39","type":"translationChoice","thai":"สี่สิบหกสิบ","roman":"sìi-sìp hòk-sìp","options":[{"text":"Fifty, sixty","correct":false},{"text":"Forty, fifty","correct":false},{"text":"Thirty, forty","correct":false},{"text":"Forty, sixty","correct":true}],"source":"Essential Thai (Higbie), p.17","parts":["สี่","สิบ","หก","สิบ"]},{"id":"so-40","type":"sentenceOrder","prompt":"Seventy, eighty","tileUnit":"word","words":{"a":{"roman":"jèt","thai":"เจ็ด"},"b":{"roman":"sìp","thai":"สิบ"},"c":{"roman":"pɛ̀ɛt","thai":"แปด"},"d":{"roman":"sìp","thai":"สิบ"},"x0":{"thai":"หนึ่ง","roman":"nɯ̀ng"},"x1":{"thai":"เก้า","roman":"kâo"}},"poolOrder":["a","b","d","x1","x0","c"],"correctOrder":["a","b","c","d"],"source":"Essential Thai (Higbie), p.17"},{"id":"sp-41","type":"speak","thai":"แปดสิบเก้าสิบ","roman":"pɛ̀ɛt-sìp kâo-sìp","meaning":"Eighty, ninety","source":"Essential Thai (Higbie), p.17","parts":["แปด","สิบ","เก้า","สิบ"]},{"id":"rule-42","type":"rule","title":"Building any two-digit number","body":"For other two-digit numbers, add the unit number again after the tens — \"45\" is see-sip-ha (forty-five), \"99\" is gao-sip-gao (ninety-nine).","source":"Essential Thai (Higbie), p.17"},{"id":"mc-44","type":"translationChoice","thai":"สี่สิบห้าหกสิบเจ็ด","roman":"sìi-sìp-hâa hòk-sìp-jèt","options":[{"text":"Forty-five, seventy-six","correct":false},{"text":"Forty-five, sixty-seven","correct":true},{"text":"Sixty-seven, ninety-nine","correct":false},{"text":"Fifty-four, seventy-six","correct":false}],"source":"Essential Thai (Higbie), p.17","parts":["สี่","สิบ","ห้า","หก","สิบ","เจ็ด"]},{"id":"so-45","type":"sentenceOrder","prompt":"Ninety-nine","tileUnit":"word","words":{"a":{"roman":"kâo","thai":"เก้า"},"b":{"roman":"sìp","thai":"สิบ"},"c":{"roman":"kâo","thai":"เก้า"},"x0":{"thai":"ศูนย์","roman":"sǔun"},"x1":{"thai":"แปด","roman":"pɛ̀ɛt"}},"poolOrder":["c","x1","b","x0","a"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.17"},{"id":"mc-46","type":"translationChoice","thai":"หกสิบเจ็ดแปดสิบสาม","roman":"hòk-sìp-jèt pɛ̀ɛt-sìp-sǎam","options":[{"text":"Seventy-six, eighty-three","correct":false},{"text":"Sixty-seven, ninety-nine","correct":false},{"text":"Sixty-seven, eighty-three","correct":true},{"text":"Forty-five, sixty-seven","correct":false}],"source":"Essential Thai (Higbie), p.17","parts":["หก","สิบ","เจ็ด","แปด","สิบ","สาม"]},{"id":"sp-47","type":"speak","thai":"สี่สิบห้าหกสิบเจ็ดแปดสิบสาม","roman":"sìi-sìp-hâa hòk-sìp-jèt pɛ̀ɛt-sìp-sǎam","meaning":"Forty-five, sixty-seven, eighty-three","source":"Essential Thai (Higbie), p.17","parts":["สี่","สิบ","ห้า","หก","สิบ","เจ็ด","แปด","สิบ","สาม"]},{"id":"wi-36","type":"wordIntro","word":{"thai":"ยี่สิบ","roman":"yîi-sìp","english":"twenty"},"source":"Essential Thai (Higbie), p.17"},{"id":"mc-37","type":"translationChoice","thai":"ยี่สิบสามสิบ","roman":"yîi-sìp sǎam-sìp","options":[{"text":"Forty, fifty","correct":false},{"text":"Twenty, thirty","correct":true},{"text":"Ten, twenty","correct":false},{"text":"Thirty, forty","correct":false}],"source":"Essential Thai (Higbie), p.17","parts":["ยี่สิบ","สาม","สิบ"]},{"id":"so-43","type":"sentenceOrder","prompt":"Twenty-one, twenty-two","tileUnit":"word","words":{"a":{"roman":"yîi-sìp","thai":"ยี่สิบ"},"b":{"roman":"èt","thai":"เอ็ด"},"c":{"roman":"yîi-sìp","thai":"ยี่สิบ"},"d":{"roman":"sɔ̌ɔng","thai":"สอง"},"x0":{"thai":"ห้า","roman":"hâa"},"x1":{"thai":"สาม","roman":"sǎam"}},"poolOrder":["b","x0","c","a","d","x1"],"correctOrder":["a","b","c","d"],"source":"Essential Thai (Higbie), p.17"}]$j$::jsonb),
  ($q$n04$q$, $q$numbers$q$, 3, $q$Hundreds and thousands$q$, $j$[{"id":"rule-48","type":"rule","title":"Hundreds","body":"\"One hundred\" is roi or neung roi. Add tens and units after roi for other hundreds, like roi-ha-sip for 150.","source":"Essential Thai (Higbie), p.17"},{"id":"rule-55","type":"rule","title":"Thousands","body":"\"One thousand\" is phan or neung phan. Add other numbers for other digits.","source":"Essential Thai (Higbie), p.18"},{"id":"wi-49","type":"wordIntro","word":{"thai":"ร้อย","roman":"rɔ́ɔi","english":"hundred"},"source":"Essential Thai (Higbie), p.17"},{"id":"mc-50","type":"translationChoice","thai":"ร้อยสองร้อยสามร้อยสี่ร้อย","roman":"rɔ́ɔi sɔ̌ɔng-rɔ́ɔi sǎam-rɔ́ɔi sìi-rɔ́ɔi","options":[{"text":"One hundred, two hundred, three hundred","correct":false},{"text":"Two hundred, three hundred, four hundred, five hundred","correct":false},{"text":"One hundred, two hundred, three hundred, four hundred","correct":true},{"text":"One hundred, three hundred, four hundred, five hundred","correct":false}],"source":"Essential Thai (Higbie), p.17","parts":["ร้อย","สอง","ร้อย","สาม","ร้อย","สี่","ร้อย"]},{"id":"so-51","type":"sentenceOrder","prompt":"Four hundred fifty","tileUnit":"word","words":{"a":{"roman":"sìi","thai":"สี่"},"b":{"roman":"rɔ́ɔi","thai":"ร้อย"},"c":{"roman":"hâa","thai":"ห้า"},"d":{"roman":"sìp","thai":"สิบ"},"x0":{"thai":"หนึ่ง","roman":"nɯ̀ng"},"x1":{"thai":"หก","roman":"hòk"}},"poolOrder":["b","c","x0","x1","a","d"],"correctOrder":["a","b","c","d"],"source":"Essential Thai (Higbie), p.17"},{"id":"mc-52","type":"translationChoice","thai":"ห้าร้อยหกร้อยเจ็ดร้อยแปดร้อย","roman":"hâa-rɔ́ɔi hòk-rɔ́ɔi jèt-rɔ́ɔi pɛ̀ɛt-rɔ́ɔi","options":[{"text":"Five hundred, six hundred, seven hundred","correct":false},{"text":"Six hundred, seven hundred, eight hundred, nine hundred","correct":false},{"text":"Five hundred, seven hundred, eight hundred, nine hundred","correct":false},{"text":"Five hundred, six hundred, seven hundred, eight hundred","corre