  ($q$n11$q$, $q$numbers$q$, 10, $q$Telling time, morning to night$q$, $j$[{"id":"rule-155","type":"rule","title":"Telling time: mong","body":"For 6am-11am, put mong after the number and add chao (\"morning\"). Afternoon hours (1pm-6pm) use bai (\"afternoon\") or yen (\"late afternoon\") instead.","source":"Essential Thai (Higbie), p.101"},{"id":"rule-164","type":"rule","title":"Evening and early-morning hours","body":"For 7pm-11pm, put thoom after the numbers 1-5. For 1am-5am, put tee BEFORE the number instead. Thiang means \"noon\".","source":"Essential Thai (Higbie), p.102"},{"id":"wi-156","type":"wordIntro","word":{"thai":"โมง","roman":"mong","english":"o'clock (daytime hour)"},"source":"Essential Thai (Higbie), p.101"},{"id":"mc-233","type":"translationChoice","thai":"กี่โมง","roman":"gìi mong","options":[{"text":"2 p.m.","correct":false},{"text":"8 p.m.","correct":false},{"text":"What time is it?","correct":true},{"text":"6 a.m.","correct":false}],"source":"Essential Thai (Higbie), p.101","parts":["กี่","โมง"]},{"id":"sp-239","type":"speak","thai":"กี่โมง","roman":"gìi mong","meaning":"What time is it?","source":"Essential Thai (Higbie), p.101","parts":["กี่","โมง"]},{"id":"wi-157","type":"wordIntro","word":{"thai":"เช้า","roman":"cháo","english":"morning"},"source":"Essential Thai (Higbie), p.101"},{"id":"so-234","type":"sentenceOrder","prompt":"6 a.m.","tileUnit":"word","words":{"a":{"roman":"hòk","thai":"หก"},"b":{"roman":"mong","thai":"โมง"},"c":{"roman":"cháo","thai":"เช้า"},"x0":{"thai":"นี้","roman":"níi"},"x1":{"thai":"เจ็ด","roman":"jèt"}},"poolOrder":["c","a","b","x1","x0"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.101"},{"id":"wi-160","type":"wordIntro","word":{"thai":"บ่าย","roman":"bàai","english":"afternoon"},"source":"Essential Thai (Higbie), p.101"},{"id":"mc-235","type":"translationChoice","thai":"บ่ายสองโมง","roman":"bàai sɔ̌ɔng mong","options":[{"text":"What time is it?","correct":false},{"text":"6 a.m.","correct":fal